sp_widget.client_script:
api.controller = function($scope,spUtil,$window,$timeout,nowAttachmentHandler) {
    var c = this;

    c.submitting = false;
    c.uploading = false;
    c.acknowledgementValidationFailed = false;
    c.attachments = c.data.attachments || [];

    /*
     * Redirect to Pending Actions in the same portal.
     */
    c.redirectToPendingActions = function() {
        var pathname = $window.location.pathname || "";
        var portalPath = "";

        /*
         * Examples:
         * /esc
         * /sp
         * /my_custom_portal
         */
        var pathParts = pathname.split("/");

        if (pathParts.length > 1 && pathParts[1]) {
            portalPath = "/" + pathParts[1];
        } else {
            portalPath = "/sp";
        }

        var redirectUrl =
            portalPath + "?id=pending_actions_asean";

        $window.location.href = redirectUrl;
    };

    c.employeeField = {
        displayValue: c.data.employeeDisplay || "",
        value: c.data.employee || "",
        name: "u_employee_name"
    };

    c.countryField = {
        displayValue: c.data.countryDisplay || "",
        value: c.data.country || "",
        name: "u_country"
    };

    c.managerField = {
        displayValue: c.data.managerDisplay || "",
        value: c.data.manager || "",
        name: "u_manager_email"
    };

    c.l2ManagerField = {
        displayValue: c.data.l2ManagerDisplay || "",
        value: c.data.l2Manager || "",
        name: "u_management_l2"
    };

    c.trainingCountryField = {
        displayValue: c.data.trainingCountryDisplay || "",
        value: c.data.trainingCountry || "",
        name: "u_training_country"
    };

    function convertToDate(value) {
        if (!value) {
            return null;
        }

        if (angular.isDate(value)) {
            return value;
        }

        var parts = value
            .toString()
            .substring(0, 10)
            .split("-");

        if (parts.length !== 3) {
            return null;
        }

        return new Date(
            parseInt(parts[0], 10),
            parseInt(parts[1], 10) - 1,
            parseInt(parts[2], 10)
        );
    }

    c.data.courseStartDate =
        convertToDate(c.data.courseStartDate);

    c.data.courseEndDate =
        convertToDate(c.data.courseEndDate);

    c.data.acknowledgement =
        c.data.acknowledgement === true ||
        c.data.acknowledgement === "true" ||
        c.data.acknowledgement === "1";

    /*
     * Store original values for Clear.
     */
    var originalData =
        angular.copy(c.data);

    var originalEmployee =
        angular.copy(c.employeeField);

    var originalCountry =
        angular.copy(c.countryField);

    var originalManager =
        angular.copy(c.managerField);

    var originalL2Manager =
        angular.copy(c.l2ManagerField);

    var originalTrainingCountry =
        angular.copy(c.trainingCountryField);

    /*
     * Submission allowed only in returned statuses.
     */
    c.canSubmitCurrentStatus = function() {
        var currentStatus =
            (c.data.statusValue || "")
                .toString()
                .toLowerCase();

        return (
            currentStatus === "return_by_manager" ||
            currentStatus === "return_by_l2" ||
            currentStatus === "return_by_hr"
        );
    };

    c.paymentRequired = function() {
        return (
            c.data.isPaymentRequired || ""
        ).toString().toLowerCase() === "yes";
    };

    /*
     * Automatically calculate L2 requirement.
     */
    c.applyL2Requirement = function(clearL2) {
        var totalCost =
            parseFloat(c.data.totalCost) || 0;

        if (totalCost > 2500) {
            c.data.l2Required = "yes";
            return;
        }

        c.data.l2Required = "no";

        if (clearL2 === true) {
            c.l2ManagerField = {
                displayValue: "",
                value: "",
                name: "u_management_l2"
            };
        }
    };

    c.calculateTotalCost = function() {
        var courseFee =
            parseFloat(c.data.courseFee) || 0;

        var otherExpenses =
            parseFloat(c.data.otherExpenses) || 0;

        c.data.totalCost = parseFloat(
            (courseFee + otherExpenses).toFixed(2)
        );

        c.applyL2Requirement(true);
    };

    c.paymentChanged = function() {
        if (!c.paymentRequired()) {
            c.data.currency = "";
            c.data.courseFee = null;
            c.data.otherExpenses = null;
            c.data.specifyOtherExpenses = "";
            c.data.totalCost = null;
            c.data.l2Required = "no";

            c.l2ManagerField = {
                displayValue: "",
                value: "",
                name: "u_management_l2"
            };

            return;
        }

        c.calculateTotalCost();
    };

    c.applyL2Requirement(false);

    c.acknowledgementChanged = function() {
        if (c.data.acknowledgement === true) {
            c.acknowledgementValidationFailed = false;
        }
    };

    /*
     * Attachments.
     */
    function attachmentSuccess(attachments) {
        c.uploading = false;

        if (angular.isArray(attachments)) {
            c.attachments = attachments;
        }

        c.refreshAttachments();

        spUtil.addInfoMessage(
            "Attachment uploaded successfully."
        );

        $scope.$applyAsync();
    }

    function attachmentError(error) {
        c.uploading = false;

        spUtil.addErrorMessage(
            error && error.message
                ? error.message
                : "Unable to upload the attachment."
        );

        $scope.$applyAsync();
    }

    c.attachmentHandler = new nowAttachmentHandler(
        attachmentSuccess,
        attachmentError
    );

    c.attachmentHandler.setParams(
        c.data.table,
        c.data.sys_id,
        24 * 1024 * 1024
    );

    c.openAttachmentPicker = function() {
        var inputElement =
            document.getElementById(
                "learningAttachmentInput"
            );

        if (inputElement) {
            inputElement.value = "";
            inputElement.click();
        }
    };

    c.uploadAttachments = function(files) {
        if (!files || !files.length) {
            return;
        }

        c.uploading = true;

        angular.forEach(files, function(file) {
            c.attachmentHandler.onFileSelect(file);
        });

        $scope.$applyAsync();
    };

    c.refreshAttachments = function() {
        c.server.get({
            action: "get_attachments",
            sys_id: c.data.sys_id
        }).then(function(response) {
            c.attachments =
                response.data.attachments || [];
        });
    };

    c.deleteAttachment = function(attachment) {
        if (!attachment || !attachment.sys_id) {
            return;
        }

        if (
            !$window.confirm(
                "Do you want to delete this attachment?"
            )
        ) {
            return;
        }

        c.server.get({
            action: "delete_attachment",
            sys_id: c.data.sys_id,
            attachment_sys_id: attachment.sys_id
        }).then(function(response) {
            if (response.data.success) {
                spUtil.addInfoMessage(
                    response.data.message
                );

                c.refreshAttachments();
                return;
            }

            spUtil.addErrorMessage(
                response.data.message ||
                "Unable to delete the attachment."
            );
        });
    };

    c.formatDate = function(value) {
        if (!value) {
            return "";
        }

        if (!angular.isDate(value)) {
            return value
                .toString()
                .substring(0, 10);
        }

        var year = value.getFullYear();
        var month = value.getMonth() + 1;
        var day = value.getDate();

        month =
            month < 10
                ? "0" + month
                : month;

        day =
            day < 10
                ? "0" + day
                : day;

        return year + "-" + month + "-" + day;
    };

    /*
     * Submit.
     */
    c.submitApplication = function(form) {
        if (c.submitting) {
            return;
        }

        /*
         * Validate current status before other fields.
         */
        if (!c.canSubmitCurrentStatus()) {
            spUtil.addErrorMessage(
                "This request can be submitted only when it is returned by Manager, L2 Manager, or HR."
            );
            return;
        }

        if (form) {
            form.$setSubmitted();
        }

        c.applyL2Requirement(false);

        /*
         * Acknowledgement is mandatory.
         */
        if (c.data.acknowledgement !== true) {
            c.acknowledgementValidationFailed = true;

            spUtil.addErrorMessage(
                "Please accept the acknowledgement before submitting."
            );

            $timeout(function() {
                var acknowledgement =
                    document.getElementById(
                        "learningAcknowledgement"
                    );

                if (acknowledgement) {
                    acknowledgement.focus();

                    if (acknowledgement.scrollIntoView) {
                        acknowledgement.scrollIntoView({
                            behavior: "smooth",
                            block: "center"
                        });
                    }
                }
            }, 0);

            return;
        }

        c.acknowledgementValidationFailed = false;

        if (
            !c.employeeField ||
            !c.employeeField.value
        ) {
            spUtil.addErrorMessage(
                "Please select Employee Name."
            );
            return;
        }

        if (
            !c.data.employeeEmail ||
            !c.data.employeeEmail.toString().trim()
        ) {
            spUtil.addErrorMessage(
                "Please enter Employee Email."
            );
            return;
        }

        if (
            !c.countryField ||
            !c.countryField.value
        ) {
            spUtil.addErrorMessage(
                "Please select Country."
            );
            return;
        }

        if (
            !c.managerField ||
            !c.managerField.value
        ) {
            spUtil.addErrorMessage(
                "Please select In Company Manager."
            );
            return;
        }

        var totalCost =
            parseFloat(c.data.totalCost) || 0;

        if (
            totalCost > 2500 &&
            (
                !c.l2ManagerField ||
                !c.l2ManagerField.value
            )
        ) {
            spUtil.addErrorMessage(
                "Please select Management L2 because Total Cost is greater than 2500."
            );
            return;
        }

        if (
            !c.data.courseTitle ||
            !c.data.courseTitle.toString().trim()
        ) {
            spUtil.addErrorMessage(
                "Please enter Course Title."
            );
            return;
        }

        if (!c.data.courseType) {
            spUtil.addErrorMessage(
                "Please select Course Type."
            );
            return;
        }

        if (!c.data.courseFormat) {
            spUtil.addErrorMessage(
                "Please select Course Format."
            );
            return;
        }

        if (
            !c.trainingCountryField ||
            !c.trainingCountryField.value
        ) {
            spUtil.addErrorMessage(
                "Please select Training Location Country."
            );
            return;
        }

        if (!c.data.courseStartDate) {
            spUtil.addErrorMessage(
                "Please select Course Start Date."
            );
            return;
        }

        if (!c.data.courseEndDate) {
            spUtil.addErrorMessage(
                "Please select Course End Date."
            );
            return;
        }

        var startDate =
            new Date(c.data.courseStartDate);

        var endDate =
            new Date(c.data.courseEndDate);

        startDate.setHours(0, 0, 0, 0);
        endDate.setHours(0, 0, 0, 0);

        if (endDate < startDate) {
            spUtil.addErrorMessage(
                "Course End Date must be after or equal to Course Start Date."
            );
            return;
        }

        if (
            c.paymentRequired() &&
            !c.data.currency
        ) {
            spUtil.addErrorMessage(
                "Please select Currency."
            );
            return;
        }

        c.submitting = true;

        c.server.get({
            action: "update",
            sys_id: c.data.sys_id,

            employee:
                c.employeeField.value,

            employeeEmail:
                c.data.employeeEmail
                    .toString()
                    .trim(),

            country:
                c.countryField.value,

            manager:
                c.managerField.value,

            l2Manager:
                c.l2ManagerField &&
                c.l2ManagerField.value
                    ? c.l2ManagerField.value
                    : "",

            courseTitle:
                c.data.courseTitle,

            courseType:
                c.data.courseType,

            courseFormat:
                c.data.courseFormat,

            trainingCountry:
                c.trainingCountryField.value,

            trainingProviderName:
                c.data.trainingProviderName || "",

            courseStartDate:
                c.formatDate(
                    c.data.courseStartDate
                ),

            courseEndDate:
                c.formatDate(
                    c.data.courseEndDate
                ),

            totalTrainingHours:
                c.data.totalTrainingHours || "",

            isPaymentRequired:
                c.data.isPaymentRequired || "no",

            currency:
                c.data.currency || "",

            courseFee:
                c.data.courseFee || "",

            otherExpenses:
                c.data.otherExpenses || "",

            specifyOtherExpenses:
                c.data.specifyOtherExpenses || "",

            totalCost:
                c.data.totalCost || "",

            acknowledgement:
                c.data.acknowledgement === true,

            comment:
                c.data.comment || ""

        }).then(
            function(response) {
                c.submitting = false;

                if (response.data.success) {
                    spUtil.addInfoMessage(
                        response.data.message ||
                        "Learning application submitted successfully."
                    );

                    $timeout(function() {
                        c.redirectToPendingActions();
                    }, 500);

                    return;
                }

                spUtil.addErrorMessage(
                    response.data.message ||
                    "Unable to submit the learning application."
                );
            },
            function() {
                c.submitting = false;

                spUtil.addErrorMessage(
                    "An unexpected error occurred while submitting."
                );
            }
        );
    };

    /*
     * Clear restores original values.
     */
    c.clearForm = function(form) {
        c.data =
            angular.copy(originalData);

        c.employeeField =
            angular.copy(originalEmployee);

        c.countryField =
            angular.copy(originalCountry);

        c.managerField =
            angular.copy(originalManager);

        c.l2ManagerField =
            angular.copy(originalL2Manager);

        c.trainingCountryField =
            angular.copy(originalTrainingCountry);

        c.data.courseStartDate =
            convertToDate(
                c.data.courseStartDate
            );

        c.data.courseEndDate =
            convertToDate(
                c.data.courseEndDate
            );

        c.data.acknowledgement =
            c.data.acknowledgement === true ||
            c.data.acknowledgement === "true" ||
            c.data.acknowledgement === "1";

        c.acknowledgementValidationFailed = false;

        c.applyL2Requirement(false);

        c.attachments =
            angular.copy(
                originalData.attachments || []
            );

        if (form) {
            form.$setPristine();
            form.$setUntouched();
        }

        spUtil.addInfoMessage(
            "Changes have been cleared. Original values have been restored."
        );
    };

    /*
     * Cancel redirects without updating.
     */
    c.cancel = function() {
        c.redirectToPendingActions();
    };
};

sp_widget.css:
.learning-page {
    width: 100%;
    min-height: 100vh;
    padding: 32px 24px 60px;
    background-color: #f3f7f9;
    box-sizing: border-box;
    font-family: Arial, Helvetica, sans-serif;
    color: #1f2937;
}

.learning-page .learning-card {
    width: 100%;
    max-width: 1450px;
    margin: 0 auto;
    overflow: visible;
    background-color: #ffffff;
    border: 1px solid #d7dee5;
    border-radius: 10px;
    box-shadow: 0 5px 16px rgba(28, 45, 64, 0.12);
    box-sizing: border-box;
}

.learning-page .learning-header {
    padding: 28px 34px 25px;
    border-bottom: 1px solid #e2e6ea;
    background-color: #ffffff;
    border-radius: 10px 10px 0 0;
}

.learning-page .header-title {
    display: flex;
    align-items: center;
    gap: 12px;
    margin: 0 0 14px;
    color: #f47b20;
    font-size: 26px;
    font-weight: 600;
    line-height: 1.3;
}

.learning-page .header-title i {
    color: #f47b20;
    font-size: 27px;
}

.learning-page .application-number {
    color: #374151;
    font-size: 17px;
}

.learning-page .learning-body {
    padding: 32px 34px 40px;
    background-color: #ffffff;
    border-radius: 0 0 10px 10px;
    box-sizing: border-box;
}

.learning-page .learning-body .form-grid {
    display: grid !important;
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    column-gap: 24px !important;
    row-gap: 22px !important;
    width: 100%;
    margin: 0;
}

.learning-page .field-block {
    display: block;
    width: 100%;
    min-width: 0;
    margin: 0;
    box-sizing: border-box;
}

.learning-page .field-block.full-width {
    grid-column: 1 / -1;
}

.learning-page .field-block > label {
    display: block;
    margin: 0 0 8px;
    color: #272d35;
    font-size: 15px;
    font-weight: 600;
}

.learning-page .required-label::before {
    content: "* ";
    color: #d9534f;
}

.learning-page .section-title {
    display: block;
    clear: both;
    margin: 31px 0 17px;
    color: #252b32;
    font-size: 20px;
    font-weight: 600;
}

.learning-page .form-control {
    display: block;
    width: 100% !important;
    height: 50px;
    margin: 0;
    padding: 10px 14px;
    border: 1px solid #c5ced8;
    border-radius: 5px;
    background-color: #ffffff;
    color: #111827;
    font-size: 15px;
    box-shadow: none;
    box-sizing: border-box;
}

.learning-page .form-control:focus {
    border-color: #f47b20;
    outline: none;
    box-shadow: 0 0 0 2px rgba(244, 123, 32, 0.14);
}

.learning-page .readonly-field {
    cursor: not-allowed;
    background-color: #eef1f3 !important;
    color: #374151;
}

.learning-page textarea.form-control,
.learning-page .textarea-control {
    height: auto;
    min-height: 92px;
    resize: vertical;
}

.learning-page .field-help-text {
    margin-top: 6px;
    color: #6b7280;
    font-size: 13px;
}

.learning-page sn-record-picker {
    display: block;
    width: 100%;
}

.learning-page sn-record-picker .select2-container {
    display: block !important;
    width: 100% !important;
}

.learning-page sn-record-picker .select2-choice {
    width: 100% !important;
    height: 50px !important;
    padding: 9px 42px 9px 14px !important;
    border: 1px solid #c5ced8 !important;
    border-radius: 5px !important;
    background: #ffffff !important;
    box-shadow: none !important;
    box-sizing: border-box !important;
}

.learning-page sn-record-picker .select2-chosen {
    line-height: 30px !important;
    color: #111827 !important;
    font-size: 15px !important;
}

.learning-page sn-record-picker .select2-arrow {
    width: 36px !important;
    border-left: 1px solid #c5ced8 !important;
    background: #ffffff !important;
}

.learning-page .acknowledgement-block {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid transparent;
    border-radius: 5px;
    background-color: #ffffff;
    box-sizing: border-box;
}

.learning-page .acknowledgement-invalid {
    border-color: #d9534f;
    background-color: #fff6f6;
}

.learning-page .acknowledgement-label {
    display: flex;
    align-items: flex-start;
    width: 100%;
    margin: 0;
    color: #333333;
    cursor: pointer;
    font-size: 14px;
    font-style: italic;
    font-weight: 500;
    line-height: 1.6;
}

.learning-page .acknowledgement-label input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin: 2px 9px 0 0;
    flex: 0 0 auto;
    cursor: pointer;
}

.learning-page .acknowledgement-text::before {
    content: "* ";
    color: #d9534f;
    font-style: normal;
    font-weight: 700;
}

.learning-page .acknowledgement-error {
    margin: 7px 0 0 27px;
    color: #d9534f;
    font-size: 13px;
    font-weight: 600;
}

.learning-page .attachment-heading {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
}

.learning-page .attachment-icon-button {
    padding: 9px 15px;
    border: 1px solid #f47b20;
    border-radius: 5px;
    background-color: #ffffff;
    color: #f47b20;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
}

.learning-page .hidden-file-input {
    display: none !important;
}

.learning-page .attachment-empty {
    padding: 18px;
    border: 1px dashed #ccd5de;
    border-radius: 5px;
    background-color: #fafbfc;
    color: #6b7280;
    text-align: center;
}

.learning-page .attachment-list {
    overflow: hidden;
    border: 1px solid #dce2e8;
    border-radius: 6px;
}

.learning-page .attachment-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 13px 15px;
    border-bottom: 1px solid #e6eaee;
}

.learning-page .attachment-row:last-child {
    border-bottom: 0;
}

.learning-page .attachment-information {
    display: flex;
    align-items: center;
    min-width: 0;
    gap: 10px;
}

.learning-page .attachment-information a {
    overflow: hidden;
    color: #0875b5;
    font-size: 14px;
    font-weight: 600;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.learning-page .attachment-file-icon {
    color: #f47b20;
    font-size: 18px;
}

.learning-page .attachment-size {
    color: #7b8490;
    font-size: 12px;
}

.learning-page .delete-attachment-button {
    padding: 5px 8px;
    border: 0;
    background: transparent;
    color: #d9534f;
    cursor: pointer;
    font-size: 16px;
}

.learning-page .form-actions {
    display: flex !important;
    align-items: center;
    justify-content: flex-end;
    gap: 14px;
    width: 100%;
    margin-top: 36px;
    padding-top: 24px;
    border-top: 1px solid #e2e6ea;
}

.learning-page .btn-action {
    min-width: 120px;
    padding: 11px 21px;
    border-radius: 5px;
    cursor: pointer;
    font-size: 14px;
    font-weight: 600;
}

.learning-page .btn-cancel {
    border: 1px solid #c5ced8;
    background-color: #ffffff;
    color: #4b5563;
}

.learning-page .btn-clear {
    border: 1px solid #f47b20;
    background-color: #ffffff;
    color: #f47b20;
}

.learning-page .btn-update {
    border: 1px solid #f47b20;
    background-color: #f47b20;
    color: #ffffff;
}

.learning-page .btn-update:hover {
    border-color: #dc6814;
    background-color: #dc6814;
}

.learning-page .btn-action[disabled] {
    cursor: not-allowed;
    opacity: 0.6;
}

.record-error-container {
    max-width: 1200px;
    margin: 30px auto;
}

@media screen and (max-width: 991px) {
    .learning-page .learning-body .form-grid {
        grid-template-columns: 1fr !important;
    }
}

@media screen and (max-width: 767px) {
    .learning-page {
        padding: 15px;
    }

    .learning-page .learning-header,
    .learning-page .learning-body {
        padding: 22px 17px;
    }

    .learning-page .attachment-heading {
        align-items: flex-start;
        flex-direction: column;
    }

    .learning-page .form-actions {
        align-items: stretch;
        flex-direction: column-reverse;
    }

    .learning-page .btn-action {
        width: 100%;
    }
}

sp_widget.script:
(function() {

    var TABLE_NAME =
        "x_1549902_asean_0_learning_application";

    /*
     * Allowed resubmission states.
     */
    var STATUS_RETURN_MANAGER =
        "return_by_manager";

    var STATUS_RETURN_L2 =
        "return_by_l2";

    var STATUS_RETURN_HR =
        "return_by_hr";

    /*
     * Destination states.
     */
    var STATUS_PENDING_MANAGER =
        "pending_manager_approval";

    var STATUS_PENDING_L2 =
        "pending_l2_approval";

    var STATUS_PENDING_HR =
        "pending_hr_review";

    data.table = TABLE_NAME;
    data.notFound = false;
    data.success = false;
    data.message = "";
    data.debugMessage = "";
    data.attachments = [];

    var sysId = "";

    if (input && input.sys_id) {
        sysId = input.sys_id.toString();
    } else {
        sysId = (
            $sp.getParameter("sys_id") || ""
        ).toString();
    }

    function getValue(record, fieldName) {
        if (
            !record ||
            !record.isValidField(fieldName)
        ) {
            return "";
        }

        return record.getValue(fieldName) || "";
    }

    function getDisplayValue(record, fieldName) {
        if (
            !record ||
            !record.isValidField(fieldName)
        ) {
            return "";
        }

        return record.getDisplayValue(fieldName) || "";
    }

    function setValue(record, fieldName, value) {
        if (
            !record ||
            !record.isValidField(fieldName)
        ) {
            return;
        }

        record.setValue(
            fieldName,
            value === null ||
            value === undefined ?
            "" :
            value
        );
    }

    function getChoiceOptions(
        tableName,
        fieldName
    ) {
        var options = [];

        var choiceGR =
            new GlideRecord("sys_choice");

        choiceGR.addQuery(
            "name",
            tableName
        );

        choiceGR.addQuery(
            "element",
            fieldName
        );

        choiceGR.addQuery(
            "inactive",
            false
        );

        choiceGR.orderBy("sequence");
        choiceGR.orderBy("label");
        choiceGR.query();

        while (choiceGR.next()) {
            options.push({
                label: choiceGR.getValue("label"),

                value: choiceGR.getValue("value")
            });
        }

        return options;
    }

    function getCurrencyOptions() {
        return [{
                label: "EUR",
                value: "EUR"
            },
            {
                label: "INR",
                value: "INR"
            },
            {
                label: "USD",
                value: "USD"
            },
            {
                label: "GBP",
                value: "GBP"
            },
            {
                label: "SGD",
                value: "SGD"
            },
            {
                label: "MYR",
                value: "MYR"
            },
            {
                label: "THB",
                value: "THB"
            },
            {
                label: "IDR",
                value: "IDR"
            },
            {
                label: "PHP",
                value: "PHP"
            },
            {
                label: "VND",
                value: "VND"
            }
        ];
    }

    function formatFileSize(sizeBytes) {
        var size =
            parseInt(sizeBytes, 10) || 0;

        if (size < 1024) {
            return size + " B";
        }

        if (size < 1024 * 1024) {
            return (
                size / 1024
            ).toFixed(1) + " KB";
        }

        return (
            size / (1024 * 1024)
        ).toFixed(1) + " MB";
    }

    function getAttachments(recordSysId) {
        var attachments = [];

        var attachmentGR =
            new GlideRecord("sys_attachment");

        attachmentGR.addQuery(
            "table_name",
            TABLE_NAME
        );

        attachmentGR.addQuery(
            "table_sys_id",
            recordSysId
        );

        attachmentGR.orderByDesc(
            "sys_created_on"
        );

        attachmentGR.query();

        while (attachmentGR.next()) {
            var attachmentSysId =
                attachmentGR.getUniqueValue();

            attachments.push({
                sys_id: attachmentSysId,

                file_name: attachmentGR.getValue(
                    "file_name"
                ),

                content_type: attachmentGR.getValue(
                    "content_type"
                ),

                size_bytes: attachmentGR.getValue(
                    "size_bytes"
                ),

                sizeDisplay: formatFileSize(
                    attachmentGR.getValue(
                        "size_bytes"
                    )
                ),

                downloadUrl: "/sys_attachment.do?sys_id=" +
                    attachmentSysId
            });
        }

        return attachments;
    }

    function isAllowedSubmitStatus(statusValue) {
        return (
            statusValue === STATUS_RETURN_MANAGER ||
            statusValue === STATUS_RETURN_L2 ||
            statusValue === STATUS_RETURN_HR
        );
    }

    function getNextStatus(currentStatus) {
        return "submitted";
    }

    /*
     * Get attachments.
     */
    if (
        input &&
        input.action === "get_attachments"
    ) {
        data.attachments =
            getAttachments(sysId);

        return;
    }

    /*
     * Delete attachment.
     */
    if (
        input &&
        input.action === "delete_attachment"
    ) {
        if (!input.attachment_sys_id) {
            data.success = false;
            data.message =
                "Attachment ID is missing.";
            return;
        }

        var attachment =
            new GlideRecord("sys_attachment");

        if (
            !attachment.get(
                input.attachment_sys_id
            )
        ) {
            data.success = false;
            data.message =
                "Attachment could not be found.";
            return;
        }

        if (
            attachment.getValue("table_name") !==
            TABLE_NAME ||
            attachment.getValue("table_sys_id") !==
            sysId
        ) {
            data.success = false;
            data.message =
                "The attachment does not belong to this application.";
            return;
        }

        attachment.deleteRecord();

        data.success = true;
        data.message =
            "Attachment deleted successfully.";

        return;
    }

    /*
     * Initial load.
     */
    if (!input) {
        data.courseTypeOptions =
            getChoiceOptions(
                TABLE_NAME,
                "u_course_type"
            );

        data.courseFormatOptions =
            getChoiceOptions(
                TABLE_NAME,
                "u_course_format"
            );

        data.currencyOptions =
            getCurrencyOptions();

        if (!sysId) {
            data.notFound = true;
            data.debugMessage =
                "The sys_id URL parameter is missing.";
            return;
        }

        var gr =
            new GlideRecord(TABLE_NAME);

        if (!gr.get(sysId)) {
            data.notFound = true;
            data.debugMessage =
                "No record was found for sys_id: " +
                sysId;
            return;
        }

        data.sys_id =
            gr.getUniqueValue();

        data.learningId =
            getDisplayValue(
                gr,
                "number"
            );

        /*
         * Send both actual value and display value.
         */
        data.statusValue =
            getValue(
                gr,
                "u_status"
            );

        data.status =
            getDisplayValue(
                gr,
                "u_status"
            );

        data.employee =
            getValue(
                gr,
                "u_employee_name"
            );

        data.employeeDisplay =
            getDisplayValue(
                gr,
                "u_employee_name"
            );

        data.employeeEmail =
            getValue(
                gr,
                "u_employee_email"
            );

        data.country =
            getValue(
                gr,
                "u_country"
            );

        data.countryDisplay =
            getDisplayValue(
                gr,
                "u_country"
            );

        data.manager =
            getValue(
                gr,
                "u_manager_email"
            );

        data.managerDisplay =
            getDisplayValue(
                gr,
                "u_manager_email"
            );

        data.l2Manager =
            getValue(
                gr,
                "u_management_l2"
            );

        data.l2ManagerDisplay =
            getDisplayValue(
                gr,
                "u_management_l2"
            );

        data.courseTitle =
            getValue(
                gr,
                "u_course_title"
            );

        data.courseType =
            getValue(
                gr,
                "u_course_type"
            );

        data.courseFormat =
            getValue(
                gr,
                "u_course_format"
            );

        data.trainingCountry =
            getValue(
                gr,
                "u_training_country"
            );

        data.trainingCountryDisplay =
            getDisplayValue(
                gr,
                "u_training_country"
            );

        if (
            data.trainingCountry &&
            data.trainingCountryDisplay ===
            data.trainingCountry
        ) {
            var countryGR =
                new GlideRecord("core_country");

            if (
                countryGR.get(
                    data.trainingCountry
                )
            ) {
                data.trainingCountryDisplay =
                    countryGR.getDisplayValue(
                        "name"
                    );
            }
        }

        data.trainingProviderName =
            getValue(
                gr,
                "u_training_provider_name"
            );

        data.courseStartDate =
            getValue(
                gr,
                "course_start_date"
            );

        data.courseEndDate =
            getValue(
                gr,
                "u_course_end_date"
            );

        data.totalTrainingHours =
            parseFloat(
                getValue(
                    gr,
                    "u_total_training_hours"
                ) || 0
            );

        data.isPaymentRequired =
            getValue(
                gr,
                "is_payment_required"
            );

        data.currency =
            getValue(
                gr,
                "currency"
            );

        data.courseFee =
            parseFloat(
                getValue(
                    gr,
                    "u_course_fee"
                ) || 0
            );

        data.otherExpenses =
            parseFloat(
                getValue(
                    gr,
                    "u_other_expenses"
                ) || 0
            );

        data.specifyOtherExpenses =
            getValue(
                gr,
                "u_specify_other_expenses"
            );

        data.totalCost =
            parseFloat(
                getValue(
                    gr,
                    "u_total_cost"
                ) || 0
            );

        /*
         * L2 requirement is derived from Total Cost.
         */
        data.l2Required =
            data.totalCost > 2500 ?
            "yes" :
            "no";

        data.acknowledgement =
            getValue(
                gr,
                "acknowlegment"
            ) === "true";

        data.comment =
            getValue(
                gr,
                "u_comment"
            );

        data.attachments =
            getAttachments(
                gr.getUniqueValue()
            );

        return;
    }

    /*
     * Submit.
     */
    if (
        input &&
        input.action === "update"
    ) {
        if (!sysId) {
            data.success = false;
            data.message =
                "Learning Application ID is missing.";
            return;
        }

        var reg =
            new GlideRecord(TABLE_NAME);

        if (!reg.get(sysId)) {
            data.success = false;
            data.message =
                "Learning application could not be found.";
            return;
        }

        /*
         * Validate the current database status.
         */
        var currentStatus =
            getValue(
                reg,
                "u_status"
            ).toString().toLowerCase();

        if (!isAllowedSubmitStatus(currentStatus)) {
            data.success = false;
            data.message =
                "This request can be submitted only when it is returned by Manager, L2 Manager, or HR.";
            return;
        }

        /*
         * Mandatory acknowledgement.
         */
        var acknowledgementAccepted =
            input.acknowledgement === true ||
            input.acknowledgement === "true" ||
            input.acknowledgement === 1 ||
            input.acknowledgement === "1";

        if (!acknowledgementAccepted) {
            data.success = false;
            data.message =
                "Please accept the acknowledgement before submitting.";
            return;
        }

        /*
         * Mandatory fields.
         */
        if (
            !input.employee ||
            !input.employeeEmail ||
            !input.country ||
            !input.manager ||
            !input.courseTitle ||
            !input.courseType ||
            !input.courseFormat ||
            !input.trainingCountry ||
            !input.courseStartDate ||
            !input.courseEndDate
        ) {
            data.success = false;
            data.message =
                "Please complete all mandatory fields.";
            return;
        }

        var submittedTotalCost =
            parseFloat(
                input.totalCost || 0
            ) || 0;

        var calculatedL2Required =
            submittedTotalCost > 2500 ?
            "yes" :
            "no";

        if (
            calculatedL2Required === "yes" &&
            !input.l2Manager
        ) {
            data.success = false;
            data.message =
                "Please select Management L2 because Total Cost is greater than 2500.";
            return;
        }

        var startDate =
            new GlideDate();

        startDate.setValue(
            input.courseStartDate
        );

        var endDate =
            new GlideDate();

        endDate.setValue(
            input.courseEndDate
        );

        if (
            endDate.getNumericValue() <
            startDate.getNumericValue()
        ) {
            data.success = false;
            data.message =
                "Course End Date must be after or equal to Course Start Date.";
            return;
        }

        /*
         * Update employee information.
         */
        setValue(
            reg,
            "u_employee_name",
            input.employee
        );

        setValue(
            reg,
            "u_employee_email",
            input.employeeEmail
        );

        setValue(
            reg,
            "u_country",
            input.country
        );

        setValue(
            reg,
            "u_manager_email",
            input.manager
        );

        /*
         * Update L2 requirement.
         */
        setValue(
            reg,
            "manager_approval_l2_required",
            calculatedL2Required
        );

        if (
            calculatedL2Required === "yes"
        ) {
            setValue(
                reg,
                "u_management_l2",
                input.l2Manager
            );
        } else {
            setValue(
                reg,
                "u_management_l2",
                ""
            );
        }

        /*
         * Course information.
         */
        setValue(
            reg,
            "u_course_title",
            input.courseTitle
        );

        setValue(
            reg,
            "short_description",
            input.courseTitle
        );

        setValue(
            reg,
            "u_course_type",
            input.courseType
        );

        setValue(
            reg,
            "u_course_format",
            input.courseFormat
        );

        setValue(
            reg,
            "u_training_country",
            input.trainingCountry
        );

        setValue(
            reg,
            "u_training_provider_name",
            input.trainingProviderName || ""
        );

        setValue(
            reg,
            "course_start_date",
            input.courseStartDate
        );

        setValue(
            reg,
            "u_course_end_date",
            input.courseEndDate
        );

        setValue(
            reg,
            "u_total_training_hours",
            input.totalTrainingHours || ""
        );

        /*
         * Payment information.
         */
        setValue(
            reg,
            "is_payment_required",
            input.isPaymentRequired || "no"
        );

        if (
            input.isPaymentRequired === "yes"
        ) {
            setValue(
                reg,
                "currency",
                input.currency || ""
            );

            setValue(
                reg,
                "u_course_fee",
                input.courseFee || ""
            );

            setValue(
                reg,
                "u_other_expenses",
                input.otherExpenses || ""
            );

            setValue(
                reg,
                "u_specify_other_expenses",
                input.specifyOtherExpenses || ""
            );

            setValue(
                reg,
                "u_total_cost",
                submittedTotalCost
            );
        } else {
            setValue(
                reg,
                "currency",
                ""
            );

            setValue(
                reg,
                "u_course_fee",
                ""
            );

            setValue(
                reg,
                "u_other_expenses",
                ""
            );

            setValue(
                reg,
                "u_specify_other_expenses",
                ""
            );

            setValue(
                reg,
                "u_total_cost",
                ""
            );
        }

        /*
         * Acknowledgement and comments.
         */
        setValue(
            reg,
            "acknowlegment",
            acknowledgementAccepted
        );

        setValue(
            reg,
            "u_comment",
            input.comment || ""
        );

        if (
            input.comment &&
            reg.isValidField("work_notes")
        ) {
            reg.work_notes =
                "Learning application resubmitted by " +
                gs.getUserDisplayName() +
                ".\n\nComments:\n" +
                input.comment;
        }

        /*
         * Move request back to the correct approval stage.
         */
        var nextStatus =
            getNextStatus(currentStatus);

        if (!nextStatus) {
            data.success = false;
            data.message =
                "Unable to determine the next approval status.";
            return;
        }

        setValue(
            reg,
            "u_status",
            nextStatus
        );

        /*
         * Keep platform approval requested.
         */
        if (
            reg.isValidField("approval")
        ) {
            reg.setValue(
                "approval",
                "requested"
            );
        }

        var updatedSysId =
            reg.update();

        if (updatedSysId) {
            data.success = true;
            data.message =
                "Learning application submitted successfully.";
        } else {
            data.success = false;
            data.message =
                "Unable to submit the learning application.";
        }
    }

})();
